<?php
require_once __DIR__.'/../src/db.php';
require_once __DIR__.'/../src/Services/ApiService.php';
if(!is_disposable_test_database_name((string)(db_profile('demo')['db_name']??''))){fwrite(STDERR,"REFUSED: scratch HTTP test requires the dedicated test profile or an explicitly enabled scratch profile as its template.\n");exit(2);}
if(active_mode()!=='LIVE'){fwrite(STDERR,"REFUSED: this harness requires current LIVE mode so its disposable server can prove LIVE routing without switching the app mode.\n");exit(2);}
$root=dirname(__DIR__);$runtime=$root.'/.runtime';if(!is_dir($runtime))mkdir($runtime,0700,true);$suffix=bin2hex(random_bytes(4));$dbName='hiker_dashboard_scratch_'.$suffix;$configPath=$runtime.'/live-scratch-config-'.$suffix.'.php';$modePath=$runtime.'/live-scratch-mode-'.$suffix.'.json';$serverLog=$runtime.'/live-scratch-server-'.$suffix.'.log';$rejectionLog=$runtime.'/rejections.log';$oldRejection=is_file($rejectionLog)?file_get_contents($rejectionLog):null;$server=null;$failed=false;$base=db_profile('demo');
$testConfig=['db_profiles'=>['demo'=>['db_host'=>$base['db_host'],'db_name'=>$dbName,'db_user'=>$base['db_user'],'db_pass'=>$base['db_pass']],'live'=>['db_host'=>$base['db_host'],'db_name'=>$dbName,'db_user'=>$base['db_user'],'db_pass'=>$base['db_pass']]],'bridge_tokens'=>['demo'=>'scratch-demo-token','live'=>'scratch-live-token'],'local_only'=>true];
file_put_contents($configPath,"<?php return ".var_export($testConfig,true).";\n");file_put_contents($modePath,json_encode(['mode'=>'LIVE']));
function assert_scratch(bool $ok,string $message): void {if(!$ok)throw new RuntimeException($message);echo "PASS $message\n";}
function run_scratch_command(array $cmd,string $root): string {$pipes=[];$proc=proc_open($cmd,[0=>['pipe','r'],1=>['pipe','w'],2=>['pipe','w']],$pipes,$root);if(!is_resource($proc))throw new RuntimeException('Could not start scratch setup command');fclose($pipes[0]);$out=stream_get_contents($pipes[1]);fclose($pipes[1]);$err=stream_get_contents($pipes[2]);fclose($pipes[2]);$status=proc_close($proc);if($status!==0)throw new RuntimeException(trim($err?:$out));return trim($out);}
function scratch_http(string $url,string $method='GET',?array $body=null,?string $token=null): array {$headers="Content-Type: application/json\r\n".(getenv('TRAILWATCH_TEST_SESSION_COOKIE')?"Cookie: ".getenv('TRAILWATCH_TEST_SESSION_COOKIE')."\r\nX-CSRF-Token: ".getenv('TRAILWATCH_TEST_CSRF_TOKEN')."\r\n":'').($token===null?'':"X-Bridge-Token: $token\r\n");$ctx=stream_context_create(['http'=>['method'=>$method,'header'=>$headers,'content'=>$body===null?'':json_encode($body,JSON_THROW_ON_ERROR),'ignore_errors'=>true,'timeout'=>3]]);$raw=@file_get_contents($url,false,$ctx);$status=0;foreach($http_response_header??[] as $h)if(preg_match('#^HTTP/\S+\s+(\d+)#',$h,$m))$status=(int)$m[1];return [$status,$raw===false?null:json_decode($raw,true),$raw];}
function launch_scratch_server(string $root,string $configPath,string $modePath,string $log,bool $allowScratch): array {$sock=stream_socket_server('tcp://127.0.0.1:0',$errno,$errstr);if(!$sock)throw new RuntimeException('Could not reserve a loopback port');$address=stream_socket_get_name($sock,false);$port=(int)substr(strrchr($address,':'),1);fclose($sock);$env=getenv();$env['TRAILWATCH_SCRATCH_TEST']='1';$env['TRAILWATCH_TEST_CONFIG']=$configPath;$env['TRAILWATCH_TEST_MODE_FILE']=$modePath;if($allowScratch)$env['TRAILWATCH_ALLOW_SCRATCH_INGEST']='1';else unset($env['TRAILWATCH_ALLOW_SCRATCH_INGEST']);$pipes=[];$proc=proc_open([PHP_BINARY,'-S','127.0.0.1:'.$port,'-t',$root.'/public',$root.'/public/router.php'],[0=>['pipe','r'],1=>['file',$log,'a'],2=>['file',$log,'a']],$pipes,$root,$env);if(!is_resource($proc))throw new RuntimeException('Could not start scratch API server');fclose($pipes[0]);$url='http://127.0.0.1:'.$port.'/api';$ready=false;for($i=0;$i<40;$i++){[$status]=scratch_http($url.'/status');if($status===200){$ready=true;break;}usleep(100000);}if(!$ready){proc_terminate($proc);throw new RuntimeException('Scratch API server did not become ready; see the scratch server log.');}return [$proc,$url];}
try{
  assert_scratch(!should_reject_live_packet('LIVE',['is_demo'=>true],'hiker_dashboard_scratch_'.$suffix,true),'scratch-only exception is gated to a disposable database name');
  assert_scratch(should_reject_live_packet('LIVE',['is_demo'=>true],'hiker_dashboard_live',true),'flagged packets remain rejected for the actual LIVE database name');
  run_scratch_command([PHP_BINARY,$root.'/tools/setup_db.php','--profile=demo','--schema-only','--config='.$configPath],$root);
  run_scratch_command([PHP_BINARY,$root.'/tools/migrate_db.php','--profile=demo','--config='.$configPath],$root);
  $pdo=utc_pdo('mysql:host='.$base['db_host'].';dbname='.$dbName.';charset=utf8mb4',$base['db_user'],$base['db_pass'],[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION]);
  foreach(['hiker_nodes','network_nodes','safe_zones','uplink_packets','system_events','site_locations'] as $table)assert_scratch((int)$pdo->query('SELECT COUNT(*) FROM '.$table)->fetchColumn()===0,'schema-only scratch database starts without seeded '.$table);
  [$server,$url]=launch_scratch_server($root,$configPath,$modePath,$serverLog,false);
  [$status,$activeSession]=scratch_http($url.'/test-sessions/active');assert_scratch($status===200&&($activeSession['session_schema_available']??false)&&empty($activeSession['active_session']),'LIVE API reports the selected site has no active session');
  [$status,$readiness]=scratch_http($url.'/live-check');$sessionCheck=array_values(array_filter($readiness['checks']??[],fn($check)=>($check['key']??'')==='test_session'))[0]??null;assert_scratch($status===200&&($sessionCheck['status']??null)==='FAIL'&&str_contains($sessionCheck['detail']??'','HTTP 409'),'LIVE readiness API explains that uplinks are rejected with HTTP 409 without a session');
  $liveToken=$testConfig['bridge_tokens']['live'];$packet=['uplink'=>['node_id'=>'H-SCRATCH','sequence_number'=>41,'latitude'=>14.598126,'longitude'=>121.0120373,'gps_accuracy_m'=>8,'satellite_count'=>6,'battery_level'=>90,'flags'=>['link_lost'=>false,'low_battery'=>false,'emergency'=>false,'turn_back_received'=>false,'test_mode'=>false]],'reception'=>['base_id'=>'BASE','path_type'=>'DIRECT'],'is_demo'=>true];
  [$status]=scratch_http($url.'/bridge/ingest','POST',$packet,'wrong-token');assert_scratch($status===401,'bridge ingest rejects a wrong token');
  [$status,$data]=scratch_http($url.'/bridge/ingest','POST',$packet,$liveToken);assert_scratch($status===422&&str_contains((string)($data['error']??''),'LIVE mode rejects'),'LIVE scratch profile rejects a flagged packet without the explicit test exception');
  assert_scratch((int)$pdo->query('SELECT COUNT(*) FROM uplink_packets')->fetchColumn()===0,'rejected LIVE packet writes no scratch uplink');
  proc_terminate($server);proc_close($server);$server=null;
  [$server,$url]=launch_scratch_server($root,$configPath,$modePath,$serverLog,true);
  [$status,$data]=scratch_http($url.'/live-check');assert_scratch($status===200&&isset($data['checks']),'read-only LIVE readiness endpoint returns checklist JSON on scratch DB');
  [$status,$data]=scratch_http($url.'/hikers','POST',['node_id'=>'H-SCRATCH','display_name'=>'Scratch hiker','phone_model'=>'test phone']);assert_scratch($status===201,'operator can register a hiker through the local API');
  [$status,$data]=scratch_http($url.'/hikers','POST',['node_id'=>'H-ARCHIVED','display_name'=>'Archived scratch hiker','is_enabled'=>false]);assert_scratch($status===201&&$data['is_enabled']===false&&(int)$pdo->query("SELECT is_enabled FROM hiker_nodes WHERE node_id='H-ARCHIVED'")->fetchColumn()===0,'new hiker can be registered inactive without losing its record');
  foreach([['node_code'=>'BASE','node_type'=>'BASE_CAMP','display_name'=>'Base Camp Node'],['node_code'=>'CHK','node_type'=>'CHECKPOINT','display_name'=>'Checkpoint Node']] as $node){[$status]=scratch_http($url.'/network-nodes','POST',$node);assert_scratch($status===201,'operator can register '.$node['node_type'].' without invented coordinates');}
  [$status,$data]=scratch_http($url.'/sites/location','PUT',['latitude'=>'','longitude'=>'','is_verified'=>false]);assert_scratch($status===200&&$data['center']===null,'site location remains explicitly unset and audited');
  [$status,$data]=scratch_http($url.'/reference-points','POST',['code'=>'JUNCTION_TEST','label'=>'Scratch trail junction','point_type'=>'JUNCTION','latitude'=>'','longitude'=>'','is_verified'=>false]);assert_scratch($status===201&&$data['unsurveyed'],'reference point can be saved as unlocated and UNSURVEYED');
  $pdo->exec("INSERT INTO test_sessions(site_id,label,phase,design,tester_code,test_point) VALUES('pup','LIVE scratch integration session','PHASE1','A','SCRATCH','PUP')");
  [$status,$data]=scratch_http($url.'/bridge/validate','POST',$packet,$liveToken);assert_scratch($status===200&&!$data['persisted'],'validation endpoint accepts authenticated loopback logical fields without committing');assert_scratch(array_key_exists('command',$data['evaluation']??[])&&$data['evaluation']['command']===null,'dry-run validation never exposes a command object');
  assert_scratch((int)$pdo->query('SELECT COUNT(*) FROM uplink_packets')->fetchColumn()===0&&(int)$pdo->query('SELECT COUNT(*) FROM packet_receptions')->fetchColumn()===0&&(int)$pdo->query('SELECT COUNT(*) FROM downlink_commands')->fetchColumn()===0&&(int)$pdo->query('SELECT COUNT(*) FROM operator_actions')->fetchColumn()===6,'dry-run validation leaves packet, reception, command, and audit tables unchanged');
  [$status,$data]=scratch_http($url.'/bridge/validate','POST',$packet,null);assert_scratch($status===401,'validation endpoint requires the bridge token');
  [$status,$data]=scratch_http($url.'/bridge/ingest','POST',$packet,$liveToken);assert_scratch($status===201&&$data['is_demo'],'scratch-only exception can exercise real flagged ingest endpoint');
  assert_scratch((int)$pdo->query('SELECT COUNT(*) FROM uplink_packets WHERE is_demo=1')->fetchColumn()===1,'scratch ingest stores the demo marker and packet only in scratch DB');
  [$status,$data]=scratch_http($url.'/hikers?include_disabled=1');assert_scratch($status===200&&count($data['hikers'])===2,'active and archived hiker registry rows are visible from the API');
  [$status,$data]=scratch_http($url.'/network-nodes');assert_scratch($status===200&&count($data['network_nodes'])===2,'site-scoped network node records are visible from the API');
  [$status,$data]=scratch_http($url.'/safe-zone');assert_scratch($status===200&&$data['safe_zone']===null,'empty live schema returns no safe zone and does not invent one');
  exec('"'.PHP_BINARY.'" "'.$root.'/tools/simulate_hikers.php" --scenario=normal_walk 2>&1',$simOut,$simStatus);assert_scratch($simStatus===3&&str_contains(implode("\n",$simOut),'Simulator refused'),'simulator refuses to run while the project active mode is LIVE');
}catch(Throwable $e){fwrite(STDERR,'FAIL '.$e->getMessage()."\n");$failed=true;}
finally{
  if(is_resource($server)){proc_terminate($server);proc_close($server);}
  try{$admin=utc_pdo('mysql:host='.$base['db_host'].';charset=utf8mb4',$base['db_user'],$base['db_pass'],[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION]);if(preg_match('/^hiker_dashboard_scratch_[a-f0-9]{8}$/',$dbName))$admin->exec('DROP DATABASE IF EXISTS `'.$dbName.'`');}catch(Throwable $e){fwrite(STDERR,"CLEANUP FAIL: could not drop generated scratch database.\n");$failed=true;}
  foreach([$configPath,$modePath,$serverLog] as $file)if(is_file($file))@unlink($file);
  if($oldRejection===null){if(is_file($rejectionLog))@unlink($rejectionLog);}else file_put_contents($rejectionLog,$oldRejection);
}
if($failed)exit(1);
echo "PASS scratch-only LIVE API integration test completed; scratch database dropped.\n";
